(()=>{"use strict";const forms=[...document.querySelectorAll("form[data-qr-form],form[data-styled-form]")];if(!forms.length)return;const lang=(document.documentElement.lang||"en").toLowerCase(),copy=lang.startsWith("fr")?{reset:"Créer un autre QR",aria:"QR créé avec succès"}:lang.startsWith("es")?{reset:"Crear otro QR",aria:"QR creado correctamente"}:lang.startsWith("pt")?{reset:"Criar outro QR",aria:"QR criado com sucesso"}:lang.startsWith("ar")?{reset:"إنشاء QR جديد",aria:"تم إنشاء رمز QR بنجاح"}:{reset:"Create another QR",aria:"QR created successfully"};
forms.forEach(form=>{const panel=form.closest(".tool-grid")?.querySelector(".preview-panel")||document.querySelector(".preview-panel"),ready=panel?.querySelector("[data-preview-ready]"),canvas=panel?.querySelector("[data-qr-canvas]"),placeholder=panel?.querySelector("[data-preview-placeholder]");if(!panel||!ready||!canvas)return;
let armed=true,lastReady=!ready.hidden;const actions=panel.querySelector(".preview-result-actions");if(actions&&!actions.querySelector(".classic-reset-row")){const row=document.createElement("div");row.className="classic-reset-row";row.hidden=true;const btn=document.createElement("button");btn.type="button";btn.className="btn secondary classic-reset";btn.textContent=copy.reset;btn.setAttribute("aria-label",copy.reset);row.appendChild(btn);actions.appendChild(row);
btn.addEventListener("click",()=>{form.reset();form.querySelectorAll('input[type="file"]').forEach(i=>{try{i.value=""}catch(_){}});form.querySelectorAll("input,textarea,select").forEach(el=>{el.dispatchEvent(new Event("input",{bubbles:true}));el.dispatchEvent(new Event("change",{bubbles:true}))});armed=true;row.hidden=true;ready.hidden=true;canvas.hidden=true;if(placeholder)placeholder.hidden=false;panel.querySelectorAll(".classic-confetti").forEach(n=>n.remove());panel.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"nearest"})});
const celebrate=()=>{if(matchMedia("(prefers-reduced-motion: reduce)").matches)return;panel.querySelectorAll(".classic-confetti").forEach(n=>n.remove());const layer=document.createElement("span");layer.className="classic-confetti";layer.setAttribute("aria-hidden","true");for(let i=0;i<12;i++){const bit=document.createElement("i");bit.style.setProperty("--i",String(i));layer.appendChild(bit)}panel.appendChild(layer);requestAnimationFrame(()=>layer.classList.add("is-live"));setTimeout(()=>layer.remove(),1000)};
const sync=()=>{const isReady=!ready.hidden&&!canvas.hidden;row.hidden=!isReady;if(isReady&&!lastReady&&armed){armed=false;ready.setAttribute("aria-label",copy.aria);ready.classList.remove("classic-ready-pop");void ready.offsetWidth;ready.classList.add("classic-ready-pop");celebrate()}if(!isReady)armed=true;lastReady=isReady};
new MutationObserver(sync).observe(ready,{attributes:true,attributeFilter:["hidden","class"]});new MutationObserver(sync).observe(canvas,{attributes:true,attributeFilter:["hidden"]});sync();}});})();
